import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../models/author.dart';import '../state/author_list_notifier.dart';import '../validators/validators.dart';import '../widgets/entity_form_scaffold.dart';
class AuthorFormScreen extends StatefulWidget{final int? id;const AuthorFormScreen({super.key,this.id});@override State<AuthorFormScreen>createState()=>_S();}
class _S extends State<AuthorFormScreen>{final key=GlobalKey<FormState>();final first=TextEditingController(),last=TextEditingController(),country=TextEditingController(),year=TextEditingController();bool dirty=false,saving=false,loading=true;Author? old;@override void initState(){super.initState();_load();}Future<void>_load()async{if(widget.id!=null){old=await context.read<AuthorListNotifier>().findById(widget.id!);if(old!=null){first.text=old!.firstName;last.text=old!.lastName;country.text=old!.country;year.text='${old!.birthYear}';}}if(mounted)setState(()=>loading=false);}@override void dispose(){for(final c in[first,last,country,year])c.dispose();super.dispose();}Future<void>leave()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Есть несохранённые изменения'),content:const Text('Выйти без сохранения?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Остаться')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Выйти'))]))??false;if(ok&&mounted){setState(()=>dirty=false);context.pop();}}Future<void>save()async{if(!key.currentState!.validate())return;setState(()=>saving=true);final a=Author(id:old?.id??0,firstName:first.text.trim(),lastName:last.text.trim(),country:country.text.trim(),birthYear:int.tryParse(year.text)??0,bookCount:old?.bookCount??0,deletedAt:old?.deletedAt);widget.id==null?await context.read<AuthorListNotifier>().create(a):await context.read<AuthorListNotifier>().update(a);if(mounted){setState(()=>dirty=false);context.go('/authors');}}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return EntityFormScaffold(title:widget.id==null?'Новый автор':'Редактирование автора',dirty:dirty,saving:saving,onSave:save,onLeaveRequested:leave,child:Form(key:key,onChanged:()=>setState(()=>dirty=true),child:Column(children:[TextFormField(controller:last,decoration:const InputDecoration(labelText:'Фамилия'),validator:(v)=>textLength(v,min:2,max:60)),const SizedBox(height:12),TextFormField(controller:first,decoration:const InputDecoration(labelText:'Имя'),validator:(v)=>textLength(v,min:2,max:60)),const SizedBox(height:12),TextFormField(controller:country,decoration:const InputDecoration(labelText:'Страна'),validator:(v)=>textLength(v,min:2,max:60)),const SizedBox(height:12),TextFormField(controller:year,decoration:const InputDecoration(labelText:'Год рождения'),validator:(v)=>intRange(v,min:1900,max:2020))])));}}
